CREATE TABLE security_events(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),event_type TEXT NOT NULL,changed_email INTEGER NOT NULL CHECK(changed_email IN(0,1)),changed_password INTEGER NOT NULL CHECK(changed_password IN(0,1)),request_id TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE rate_limit_buckets(bucket_key TEXT NOT NULL,window_start INTEGER NOT NULL,expires_at INTEGER NOT NULL,count INTEGER NOT NULL CHECK(count>=0),PRIMARY KEY(bucket_key,window_start));
CREATE INDEX rate_expiry ON rate_limit_buckets(expires_at);
CREATE INDEX sessions_user ON sessions(user_id,namespace,auth_version);
CREATE TABLE mutation_contexts(operation_id TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id),kind TEXT NOT NULL,expected_versions_json TEXT NOT NULL DEFAULT '{}',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,ok INTEGER NOT NULL CHECK(ok=1));
CREATE TRIGGER valid_mutation BEFORE INSERT ON mutation_contexts WHEN NEW.ok!=1 BEGIN SELECT RAISE(ABORT,'MUTATION_CONFLICT'); END;
CREATE TABLE migration_runs(id TEXT PRIMARY KEY,source_digest TEXT NOT NULL,source_schema TEXT NOT NULL,target_identity TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('SNAPSHOT','IMPORTING','IMPORTED','VERIFIED','FAILED')),cutoff_at TEXT NOT NULL,started_at TEXT NOT NULL,verified_at TEXT);
CREATE TABLE migration_chunks(run_id TEXT NOT NULL REFERENCES migration_runs(id),table_name TEXT NOT NULL,chunk_no INTEGER NOT NULL CHECK(chunk_no>=0),digest TEXT NOT NULL,row_count INTEGER NOT NULL CHECK(row_count>=0),applied_at TEXT NOT NULL,PRIMARY KEY(run_id,table_name,chunk_no));
CREATE TABLE deployment_state(id INTEGER PRIMARY KEY CHECK(id=1),environment_id TEXT NOT NULL,database_identity TEXT NOT NULL,schema_version INTEGER NOT NULL,source_digest TEXT,mode TEXT NOT NULL CHECK(mode IN('CLOSED','VERIFIED','OPEN')),verified_at TEXT);
INSERT INTO deployment_state VALUES(1,'unconfigured','',2,NULL,'CLOSED',NULL);
CREATE VIEW catalog_products AS SELECT p.*,c.name category_name,c.slug category_slug,c.is_active category_active,i.quantity,i.version inventory_version,pr.id promotion_id,pr.version promotion_version,CASE WHEN pr.id IS NULL THEN p.base_price_cents WHEN pr.kind='FINAL_PRICE' THEN pr.value ELSE CAST((p.base_price_cents*(10000-pr.value)+5000)/10000 AS INTEGER) END effective_price_cents,CASE WHEN pr.id IS NULL THEN NULL ELSE json_object('id',pr.id,'product_id',pr.product_id,'category_id',pr.category_id,'kind',pr.kind,'value',pr.value,'starts_at',pr.starts_at,'ends_at',pr.ends_at,'terms',pr.terms,'is_active',pr.is_active,'version',pr.version) END promotion_json FROM products p JOIN categories c ON c.id=p.category_id JOIN inventory i ON i.product_id=p.id LEFT JOIN promotions pr ON pr.id=(SELECT id FROM promotions WHERE is_active=1 AND starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (product_id=p.id OR category_id=p.category_id) ORDER BY product_id IS NOT NULL DESC LIMIT 1);
CREATE VIEW order_documents AS SELECT o.id,o.public_id,o.user_id,json_object('publicId',o.public_id,'status',o.status,'paymentStatus',o.payment_status,'subtotal_cents',o.subtotal_cents,'total_cents',o.total_cents,'currency',o.currency,'createdAt',o.created_at,'updatedAt',o.updated_at,'version',o.version,'simulationOnly',json('true'),'customer',json_object('id',u.id,'name',u.name,'email',u.email),'deliveryAddress',json_object('recipient',o.recipient_snapshot,'phone',o.phone_snapshot,'region',o.region_snapshot,'province',o.province_snapshot,'district',o.district_snapshot,'street',o.street_snapshot,'reference',o.reference_snapshot),'items',json((SELECT json_group_array(json_object('product_id',product_id,'sku_snapshot',sku_snapshot,'name',name_snapshot,'unit_price_cents',unit_price_cents,'quantity',quantity,'line_total_cents',line_total_cents)) FROM order_items WHERE order_id=o.id)),'payments',json((SELECT json_group_array(json_object('id',id,'outcome',outcome,'amount_cents',amount_cents,'currency',currency,'createdAt',created_at)) FROM simulated_payments WHERE order_id=o.id)),'history',json((SELECT json_group_array(json_object('fromStatus',from_status,'toStatus',to_status,'createdAt',created_at)) FROM order_status_history WHERE order_id=o.id))) document FROM orders o JOIN users u ON u.id=o.user_id;
